window.pdfLines=async no=>{const h=await (await fetch(`/ai/aia/selectAPTLttotPblancDetail.do?houseManageNo=${no}&pblancNo=${no}`)).text();
 const u=(h.match(/https:\/\/static\.applyhome\.co\.kr\/ai\/aia\/getAtchmnfl\.do\?[^"']+/)||[])[0]; if(!u) return null;
 const doc=await pdfjsLib.getDocument({data:await (await fetch(u.replace(/&amp;/g,'&'))).arrayBuffer()}).promise; const out=[];
 for(let i=1;i<=doc.numPages;i++){const c=await (await doc.getPage(i)).getTextContent();
   const it=c.items.filter(t=>t.str.trim()).map(t=>({x:t.transform[4],y:t.transform[5],h:Math.abs(t.transform[3])||8,s:t.str.trim()})).sort((a,b)=>b.y-a.y);
   const rows=[]; it.forEach(t=>{const r=rows[rows.length-1]; if(r&&Math.abs(r.y-t.y)<=Math.max(2.5,t.h*0.45)) r.it.push(t); else rows.push({y:t.y,it:[t]});});
   rows.forEach(r=>out.push(r.it.sort((a,b)=>a.x-b.x).map(t=>t.s).join(' ')));}
 return out;};

window.prep=L=>L.map(l=>l.replace(/(최상층|최고층|펜트하우스층)/g,'999 층').replace(/(\d)\s*층\s*~\s*(\d)/g,'$1~$2'));

window.parseP=lines=>{
 const MONEY=/^\s*(?:\d{1,3}(?:,\d{3}){2,}|-)(?:\s+(?:\d{1,3}(?:,\d{3})+|-))+/, FU=/^(?:\S+\s+)*?(\d+(?:\s*[-~]\s*\d+)?\s*층(?:\s*이상)?)\s+(\d{1,4})\s*$/;
 const L=[]; for(let i=0;i<lines.length;i++){const a=lines[i];
   if(MONEY.test(a)){const nx=lines[i+1]||'', pv=L[L.length-1]||''; if(FU.test(nx)){L.push(nx+' '+a);i++;continue;} if(FU.test(pv)){L[L.length-1]=pv+' '+a;continue;}}
   L.push(a);}
 const MON='((?:(?:\\d{1,3}(?:,\\d{3})+|-)\\s+){2,5}\\d{1,3}(?:,\\d{3})+)';
 const reF=new RegExp('(\\d+(?:\\s*[-~]\\s*\\d+)?)\\s*(?:층)?\\s*(?:이상|이하)?\\s+(\\d{1,4})\\s+'+MON);
 const reT=new RegExp('(?:^|\\s)\\d{2,3}[A-Z]+\\s+(\\d{1,4})\\s+'+MON);
 const rows=[];
 L.forEach(l=>{let lo,u,ms; let m=l.match(reF); if(m){lo=+m[1].match(/\d+/)[0];u=+m[2];ms=m[3];} else {m=l.match(reT); if(!m) return; lo=9999;u=+m[1];ms=m[2];}
   const n=ms.trim().split(/\s+/).map(x=>x==='-'?0:+x.replace(/,/g,''));
   let tot=null; for(let k=2;k<n.length;k++){const s=n.slice(0,k).reduce((a,b)=>a+b,0); if(s===n[k]&&s>=5e7){tot=n[k];break;}}
   if(tot!=null) rows.push({lo,u,tot,T:lo===9999});});
 const B=[]; let c=null; rows.forEach(r=>{if(!c||r.T||r.lo<=c.last){c={r:[],last:-1};B.push(c);} c.r.push(r); c.last=r.lo;});
 return B.map(b=>{const U=b.r.reduce((a,r)=>a+r.u,0); return {units:U,avg:b.r.reduce((a,r)=>a+r.u*r.tot,0)/U/1e4,min:Math.min(...b.r.map(r=>r.tot))/1e4,max:Math.max(...b.r.map(r=>r.tot))/1e4};});};

window.matchP=(B,api)=>{ let r=m0(B,api); if(r) return r; const t=api.filter(a=>/T$/.test(a[0])); if(!t.length) return null;
  const api2=[...api.filter(a=>!/T$/.test(a[0])),...t]; return m0(B,api2); };

window.labelMatch=(lines,api)=>{
 const MONEY=/^\s*(?:\d{1,3}(?:,\d{3}){2,}|-)(?:\s+(?:\d{1,3}(?:,\d{3})+|-))+/, FU=/^(?:\S+\s+)*?(\d+(?:\s*[-~]\s*\d+)?\s*층(?:\s*이상)?)\s+(\d{1,4})\s*$/;
 const L=[]; for(let i=0;i<lines.length;i++){const a=lines[i];
   if(MONEY.test(a)){const nx=lines[i+1]||'', pv=L[L.length-1]||''; if(FU.test(nx)){L.push(nx+' '+a);i++;continue;} if(FU.test(pv)){L[L.length-1]=pv+' '+a;continue;}}
   L.push(a);}
 const MON='((?:(?:\\d{1,3}(?:,\\d{3})+|-)\\s+){2,5}\\d{1,3}(?:,\\d{3})+)';
 const reF=new RegExp('(\\d+(?:\\s*[-~]\\s*\\d+)?)\\s*(?:층)?\\s*(?:이상|이하)?\\s+(\\d{1,4})\\s+'+MON), reT=new RegExp('(?:^|\\s)(\\d{2,3}[A-Z]+)\\s+(\\d{1,4})\\s+'+MON);
 const types=new Set(api.map(a=>a[0])); const norm=t=>(t||'').replace(/^[A-Z]+(?=\d)/,'').replace(/형$/,'');
 const labAt=l=>{const tk=l.trim().split(/\s+/); if(/^(동|호|층|세대|호실)/.test(tk[1]||'')) return null; const t=norm(tk[0]); return types.has(t)?t:null;};
 const B=[]; let c=null;
 L.forEach((l,i)=>{ const lab=labAt(l);
   let m=l.match(reF), lo,u,ms; if(m){lo=+m[1].match(/\d+/)[0];u=+m[2];ms=m[3];} else {m=l.match(reT); if(m){lo=9999;u=+m[2];ms=m[3];}}
   let tot=null; if(m){const n=ms.trim().split(/\s+/).map(x=>x==='-'?0:+x.replace(/,/g,'')); for(let k=2;k<n.length;k++){const s=n.slice(0,k).reduce((a,b)=>a+b,0); if(s===n[k]&&s>=5e7){tot=n[k];break;}}}
   if(tot==null){ if(lab&&c&&!c.lab&&i-c.i1<=2) c.lab=lab; else if(lab) c&&(c.next=lab); return; }  // 라벨만 있는 줄
   const newB=!c||lo<=c.last||(lab&&c.lab&&lab!==c.lab)||i-c.i1>6;
   if(newB){ c={rows:[],last:-1,lab:lab||(c&&c.next&&i-c.i1<=3?c.next:null),i0:i,i1:i}; B.push(c);} 
   if(lab&&!c.lab) c.lab=lab; c.rows.push({u,tot}); c.last=lo; c.i1=i; c.next=null; });
 const LB=B.filter(b=>b.lab); B.forEach(b=>{ if(b.lab) return; let best=1e9,lb=null; LB.forEach(x=>{const d=x.i0>b.i1?x.i0-b.i1:b.i0>x.i1?b.i0-x.i1:0; if(d<best){best=d;lb=x.lab;}}); if(best<=12) b.lab=lb; });
 const g={}; for(const b of B){ if(!b.lab) continue; (g[b.lab]??=[]).push(b); }
 const res=(G)=>api.map(([t,U,mx])=>{const R=(G[t]||[]).flatMap(b=>b.rows); const u=R.reduce((a,r)=>a+r.u,0); return {t,U,mx,u,R};});
 let r=res(g); const ok=x=>x.every(o=>o.u===o.U&&o.R.length&&Math.abs(Math.max(...o.R.map(q=>q.tot))/1e4-o.mx)<1);
 if(!ok(r)){ // 라벨 블록이 중복(정정 전·후 등)이면 중복 제거
   const g2={}; for(const [t,bs] of Object.entries(g)){const seen=new Set(); g2[t]=bs.filter(b=>{const k=b.rows.map(q=>q.u+':'+q.tot).join(','); if(seen.has(k)) return false; seen.add(k); return true;});}
   r=res(g2); if(!ok(r)){
   const g3={}; for(const [t,U,mx] of api){ const bs=g[t]||[]; let pick=null;
     for(let e=bs.length;e>0&&!pick;e--){ let u=0; for(let s2=e-1;s2>=0;s2--){ u+=bs[s2].rows.reduce((a,q)=>a+q.u,0); if(u===U){pick=bs.slice(s2,e);break;} if(u>U) break; } }
     g3[t]=pick||[]; }
   r=res(g3); if(!ok(r)) return null; } }
 return {rows:r.map(o=>[o.t,Math.round(o.R.reduce((a,q)=>a+q.u*q.tot,0)/o.u/1e4),Math.round(Math.min(...o.R.map(q=>q.tot))/1e4),Math.round(Math.max(...o.R.map(q=>q.tot))/1e4),o.u]),chk:'exact'};};

window.roomMatch=(lines,api)=>{ const re=/(?:^|\s)(\d{3,4})\s+((?:\d{1,3}(?:,\d{3})+\s+){1,3}\d{1,3}(?:,\d{3})+)/; const rows=[];
 lines.forEach(l=>{const m=l.match(re); if(!m) return; const n=m[2].trim().split(/\s+/).map(x=>+x.replace(/,/g,'')); let tot=null;
   for(let k=2;k<n.length;k++){const s=n.slice(0,k).reduce((a,b)=>a+b,0); if(s===n[k]&&s>=5e7){tot=n[k];break;}} if(tot!=null) rows.push(tot);});
 const need=api.reduce((a,x)=>a+x[1],0); if(rows.length<need) return null;
 for(const start of [0, rows.length-need]){ let p=start, out=[], ok=true;
   for(const [t,U,mx] of api){ const g=rows.slice(p,p+U); p+=U; if(g.length<U||Math.abs(Math.max(...g)/1e4-mx)>=1){ok=false;break;}
     out.push([t,Math.round(g.reduce((a,b)=>a+b,0)/U/1e4),Math.round(Math.min(...g)/1e4),Math.round(Math.max(...g)/1e4),U]); }
   if(ok) return {rows:out,chk:'exact'}; }
 return null;};

window.orderMatch=(P,api)=>{
 const types=new Set(api.map(a=>a[0])); const norm=t=>(t||'').replace(/^[A-Z]+(?=\d)/,'').replace(/형$/,'');
 const labs=[]; P.forEach((l,i)=>{const tk=l.trim().split(/\s+/); if(/^(동|호|층|세대|호실)/.test(tk[1]||'')) return; const t=norm(tk[0]); if(types.has(t)) labs.push({i,t});});
 // parseP와 같은 블록 + 시작 줄 번호
 const lines=P; const idxRows=[]; const MON='((?:(?:\\d{1,3}(?:,\\d{3})+|-)\\s+){2,5}\\d{1,3}(?:,\\d{3})+)';
 const reF=new RegExp('(\\d+(?:\\s*[-~]\\s*\\d+)?)\\s*(?:층)?\\s*(?:이상|이하)?\\s+(\\d{1,4})\\s+'+MON), reT=new RegExp('(?:^|\\s)\\d{2,3}[A-Z]+\\s+(\\d{1,4})\\s+'+MON);
 lines.forEach((l,i)=>{let lo,u,ms,T=false; let m=l.match(reF); if(m){lo=+m[1].match(/\d+/)[0];u=+m[2];ms=m[3];} else {m=l.match(reT); if(!m) return; lo=9999;u=+m[1];ms=m[2];T=true;}
   const n=ms.trim().split(/\s+/).map(x=>x==='-'?0:+x.replace(/,/g,'')); let tot=null; for(let k=2;k<n.length;k++){const s=n.slice(0,k).reduce((a,b)=>a+b,0); if(s===n[k]&&s>=5e7){tot=n[k];break;}}
   if(tot!=null) idxRows.push({i,lo,u,tot,T});});
 const B=[]; let c=null; idxRows.forEach(r=>{if(!c||r.T||r.lo<=c.last){c={r:[],last:-1,i0:r.i};B.push(c);} c.r.push(r); c.last=r.lo;});
 const BB=B.map(b=>{const U=b.r.reduce((a,r)=>a+r.u,0); return {i0:b.i0,units:U,avg:b.r.reduce((a,r)=>a+r.u*r.tot,0)/U/1e4,min:Math.min(...b.r.map(r=>r.tot))/1e4,max:Math.max(...b.r.map(r=>r.tot))/1e4};});
 for(let s0=0;s0<BB.length;s0++){
   const first={}; labs.filter(x=>x.i>=BB[s0].i0-3).forEach(x=>{ if(!(x.t in first)) first[x.t]=x.i; });
   const api2=[...api].sort((a,b)=>(first[a[0]]??1e9)-(first[b[0]]??1e9));
   const r=matchP(BB.slice(s0),api2); if(r){ const mp=Object.fromEntries(r.rows.map(x=>[x[0],x])); return {rows:api.map(a=>mp[a[0]]),chk:r.chk}; } }
 return null;};

window.seqRows=(P)=>{const R=[];for(const s of P){const tk=s.split(/\s+/);const v=tk.map(t=>/^\d{1,3}(,\d{3})+$/.test(t)?+t.replace(/,/g,''):((t==='-'||t==='0')?0:null));
 for(let i=0;i<tk.length-1;i++){ if(v[i]==null||v[i]<1e6) continue; let hit=null;
  for(const k of [2,3]){ if(i+k<tk.length&&v.slice(i,i+k+1).every(x=>x!=null)){const sm=v.slice(i,i+k).reduce((a,b)=>a+b,0); if(sm===v[i+k]&&v[i+k]>=5e7){hit=[k,v[i+k]];break;}}}
  if(!hit&&v[i]>=5e7&&v[i+1]!=null&&v[i+1]>0&&[10,20].some(d=>Math.abs(v[i+1]*d-v[i])<=d)) hit=[0,v[i]];
  if(!hit) continue; const pre=tk.slice(0,i); let u=null; const li=pre.map((t,j)=>/층$/.test(t)?j:-1).filter(j=>j>=0).pop();
  if(li!=null&&li>=0){const t=pre.slice(li+1).find(t=>/^\d+$/.test(t)); if(t) u=+t;}
  if(u==null){const nums=pre.filter(t=>/^\d+$/.test(t)); if(nums.length) u=+nums[nums.length-1];}
  if(u) R.push([u,hit[1]/1e4,s]); break; }}
 return R;};

window.seqMatch=(P,api)=>{const R=seqRows(P); if(!R.length) return null;
 const orders=[api.slice()]; const lab=api.map(a=>[a,P.findIndex(s=>new RegExp('(^|\\s)'+a[0].replace(/([A-Z]+)$/,'$1')+'(\\s|$)').test(s))]); if(lab.every(x=>x[1]>=0)) orders.push(lab.sort((a,b)=>a[1]-b[1]).map(x=>x[0]));
 for(const ord of orders){ for(let skip=0;skip<Math.min(R.length,40);skip++){ let j=skip, ok=true; const rows=[];
   for(const [ty,n,top] of ord){ let u=0,w=0,mn=1e12,mx=0; while(j<R.length&&u<n){u+=R[j][0];w+=R[j][0]*R[j][1];mn=Math.min(mn,R[j][1]);mx=Math.max(mx,R[j][1]);j++;}
     if(u!==n||Math.abs(mx-top)>1){ok=false;break;} rows.push([ty,Math.round(w/u),Math.round(mn),Math.round(mx),n]); }
   if(ok) return {rows:api.map(a=>rows.find(r=>r[0]===a[0])),chk:'seq'}; } }
 return null;};
